    ,cspu_id
    ,model_id
    ,item_id
    ,shop_id
FROM srdi_mart.dim_sr_data_warehouse_pb_all_cspu_link_analysis_hf
WHERE grass_region = ${grass_region}
AND local_date = ${local_date}
;
--sql_divide_splitter--

create temporary view all_cspu_item_${grass_region_without_quote} as
select local_hour
    ,cspu_id
    ,item_id
from all_cspu_model_${grass_region_without_quote}
group by 1,2,3
;
--sql_divide_splitter--

create temporary view traffic_raw_${grass_region_without_quote} as
select local_hour
     ,user_id
     ,item_id
     ,model_id
     ,sum(imp_cnt) imp_cnt
     ,sum(seller_gmv) gmv
    from srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
where grass_region = ${grass_region}
and local_date = ${local_date}
and mapping_general = '__ALL__'
group by 1,2,3,4
;
--sql_divide_splitter--

create temporary view exp_group_${grass_region_without_quote} as
SELECT
    user_id
     ,case when exp_group_id >= 452524 then 'control'
        else 'treatment' end as exp_group_type
FROM srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE grass_region in (${grass_region})
  AND local_date = ${local_date}
  AND is_assignment_log = 1
  and exp_group_id between 452506 and 452525
;
--sql_divide_splitter--

create temporary view traffic_exp_${grass_region_without_quote} as
select local_hour
    ,exp_group_type
    ,item_id
    ,model_id
    ,sum(imp_cnt) imp_cnt
    ,sum(gmv) gmv
    from traffic_raw_${grass_region_without_quote} a
inner join exp_group_${grass_region_without_quote} b
on a.user_id = b.user_id
group by 1,2,3,4
;
--sql_divide_splitter--

create temporary view model_traffic_hourly_${grass_region_without_quote} as
select t1.local_hour
    ,t1.model_id
    ,t1.item_id
    ,t1.shop_id
    ,t1.cspu_id
    , SUM (CASE WHEN t2.exp_group_type = 'control' THEN imp_cnt else 0 END) control_imp_cnt
    , SUM (CASE WHEN t2.exp_group_type = 'treatment' THEN imp_cnt else 0 END) treatment_imp_cnt
    , SUM (CASE WHEN t2.exp_group_type = 'control' THEN gmv else 0 END) control_gmv
    , SUM (CASE WHEN t2.exp_group_type = 'treatment' THEN gmv else 0 END) treatment_gmv
from (
    select local_hour
        ,model_id
        ,item_id
        ,shop_id
        ,cspu_id
    from all_cspu_model_${grass_region_without_quote}
)t1
left join(
    (
        select a.local_hour
             ,a.model_id
             ,a.item_id
             ,a.shop_id
             ,a.cspu_id
             ,b.exp_group_type
            ,sum(imp_cnt) imp_cnt
            ,0 as gmv
        from all_cspu_model_${grass_region_without_quote} a
            inner join traffic_exp_${grass_region_without_quote} b
        on a.local_hour = b.local_hour
            and a.item_id = b.item_id
        group by 1,2,3,4,5,6
    )
    UNION ALL
    (
        select a.local_hour
             ,a.model_id
             ,a.item_id
             ,a.shop_id
             ,a.cspu_id
             ,b.exp_group_type
            ,0 as imp_cnt
            ,sum(gmv) as gmv
        from all_cspu_model_${grass_region_without_quote} a
            inner join traffic_exp_${grass_region_without_quote} b
        on a.local_hour = b.local_hour
            and a.model_id = b.model_id
        group by 1,2,3,4,5,6
    )
)t2
on t1.local_hour = t2.local_hour
and t1.model_id = t2.model_id
and t1.item_id = t2.item_id
and t1.shop_id = t2.shop_id
and t1.cspu_id = t2.cspu_id
group by 1,2,3,4,5
;
--sql_divide_splitter--

create temporary view traffic_all_${grass_region_without_quote} as
select local_hour
     ,model_id
     ,item_id
     ,sum(imp_cnt) imp_cnt
     ,sum(gmv) gmv
from traffic_raw_${grass_region_without_quote}
group by 1,2,3
;

--sql_divide_splitter--

create temporary view cspu_model_level_${grass_region_without_quote} as
select a.local_hour
     ,cspu_id
     ,sum(gmv) cspu_gmv
from traffic_all_${grass_region_without_quote} a
inner join all_cspu_model_${grass_region_without_quote} b
on a.local_hour = b.local_hour
and a.model_id = b.model_id
group by 1,2
;
--sql_divide_splitter--

create temporary view cspu_item_level_${grass_region_without_quote} as
select a.local_hour
     ,cspu_id
     ,sum(imp_cnt) cspu_imp_cnt
from traffic_all_${grass_region_without_quote} a
inner join all_cspu_item_${grass_region_without_quote} b
on a.local_hour = b.local_hour
and a.item_id = b.item_id
group by 1,2
;
--sql_divide_splitter--

create temporary view model_cspu_traffic_daily_${grass_region_without_quote} as
select model_id
     ,item_id
     ,shop_id
     ,sum(control_imp_cnt) control_imp_cnt
     ,sum(treatment_imp_cnt) treatment_imp_cnt
     ,sum(control_gmv) control_gmv
     ,sum(treatment_gmv) treatment_gmv
     ,sum(cspu_gmv) cspu_gmv
     ,sum(cspu_imp_cnt) cspu_imp_cnt
from model_traffic_hourly_${grass_region_without_quote} a
left join cspu_model_level_${grass_region_without_quote} b
on a.local_hour = b.local_hour
and a.cspu_id = b.cspu_id
left join cspu_item_level_${grass_region_without_quote} c
on a.local_hour = c.local_hour
and a.cspu_id = c.cspu_id
group by 1,2,3
;
--sql_divide_splitter--

create temporary view winner_${grass_region_without_quote} as
select model_id
from srdi_mart.dim_sr_data_warehouse_pb_one_variation_model_analysis_hf
where grass_region = ${grass_region} AND local_date = ${local_date}
and business_type in (3,4)
group by 1
;
--sql_divide_splitter--

create temporary view normalization_${grass_region_without_quote} as
SELECT 1.0000*count(distinct case when exp_group_type = 'treatment' then user_id end)/count(distinct case when exp_group_type = 'control' then user_id end)
    as normalization_value
from exp_group_${grass_region_without_quote}
;
--sql_divide_splitter--

create temporary view model_join_${grass_region_without_quote} as
select a.model_id
    ,a.item_id
    ,a.shop_id
    ,if(b.model_id is not null,1,0) is_win_day
    ,coalesce(control_imp_cnt,0) as control_imp_cnt
    ,coalesce(treatment_imp_cnt,0) as treatment_imp_cnt
    ,coalesce(control_gmv,0) as control_gmv
    ,coalesce(treatment_gmv,0) as treatment_gmv
    ,coalesce(imp_cnt,0) imp_cnt
    ,coalesce(gmv,0) gmv
    ,coalesce(cspu_imp_cnt,0) as cspu_imp_cnt
    ,coalesce(cspu_gmv,0) as cspu_gmv
    ,c.normalization_value
from model_cspu_traffic_daily_${grass_region_without_quote} a
left join winner_${grass_region_without_quote} b
on a.model_id = b.model_id
left join normalization_${grass_region_without_quote} c
on 1=1
left join (
    select item_id
         ,sum(imp_cnt) imp_cnt
    from traffic_all_${grass_region_without_quote}
    group by 1
)d
on a.item_id = d.item_id
left join(
    select model_id
         ,sum(gmv) gmv
    from traffic_all_${grass_region_without_quote}
    group by 1
)e
on a.model_id = e.model_id
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_reward_model_exp_level_1d partition(grass_region = ${grass_region}, local_date = ${local_date})
select model_id
     ,item_id
     ,shop_id
     ,is_win_day
     ,imp_cnt
     ,gmv
     ,control_imp_cnt
     ,treatment_imp_cnt/normalization_value as treatment_imp_cnt_normal -- 归一后的
     ,control_gmv
     ,treatment_gmv/normalization_value as treatment_gmv_normal -- 归一后的
     ,cspu_imp_cnt
     ,cspu_gmv
     ,case when control_imp_cnt>0 then 1.0000*treatment_imp_cnt/normalization_value/control_imp_cnt-1
         when treatment_imp_cnt>0 then 1.0
     else 0 end as imp_cnt_1d_uplift_pct

    ,normalization_value as normalization_value
    ,treatment_imp_cnt as treatment_imp_cnt
    ,treatment_gmv as treatment_gmv
from model_join_${grass_region_without_quote}
where item_id > 0 and shop_id > 0
;
